"""Board-style case sets (scenario + 3 multiple-choice questions) for the biochemistry chapters, modeled on the
item-set format of the National Board Dental Hygiene Examination. Output: sections/boardsets/boardsets.json {pageId: html}."""
import json
SETS=[
(8,597142,'A teenager with new cavities','A 19-year-old college student has four new early (incipient) carious lesions. He sips sweetened soda through the afternoon and keeps hard candy in his mouth while he studies. The hygienist suggests sugar-free gum sweetened with xylitol.',
 [('Sucrose, the sugar in soda and candy, is a disaccharide made of',['glucose + galactose','glucose + fructose','glucose + glucose','fructose + galactose'],1,'Sucrose is glucose joined to fructose; lactose is glucose + galactose, and maltose is two glucose units (Section 8.6).'),
  ('Plaque bacteria such as <em>Streptococcus mutans</em> ferment sugars into a product that lowers plaque pH and dissolves enamel. That product is',['lactic acid','ethanol','glycogen','cellulose'],0,'Bacterial fermentation of sugar produces lactic acid; below about pH 5.5 enamel starts to demineralize.'),
  ('Xylitol is recommended because it',['is a sugar alcohol that cavity-causing bacteria cannot ferment to acid','is a polysaccharide too large to be digested','is an amine that neutralizes plaque acid','is a reducing sugar that raises plaque pH'],0,'Xylitol is a five-carbon sugar alcohol (polyol). It tastes sweet, but <em>S. mutans</em> cannot ferment it, so no acid forms.')]),
(9,597151,'A patient on a statin','A 58-year-old man with generalized periodontitis lists atorvastatin on his health history for high cholesterol. His last lipid panel showed LDL 165 mg/dL and triglycerides 210 mg/dL. Before scaling, the hygienist gives a local anesthetic injection.',
 [('A triglyceride is',['glycerol joined by three ester bonds to three fatty acids','three glucose units joined by glycosidic bonds','a steroid with four fused rings','a phospholipid with a choline head'],0,'Triglycerides (triacylglycerols) are triesters of glycerol (Section 9.2).'),
  ('Cholesterol is classified as a',['steroid, a non-hydrolyzable lipid','triglyceride','glycerophospholipid','fatty acid'],0,'Cholesterol has the four fused rings of a steroid and contains no ester to hydrolyze (Section 9.6).'),
  ('A local anesthetic must cross the nerve cell membrane before it can work. Which form of the anesthetic crosses the phospholipid bilayer?',['The uncharged (free base) form, because the interior of the bilayer is nonpolar','The charged (ammonium) form, because the bilayer interior is polar','Either form equally','Neither; it enters through the cell&rsquo;s glucose transporters'],0,'Only the uncharged form dissolves in the nonpolar tails of the bilayer (Section 9.5). Inflamed, acidic tissue shifts more drug to the charged form, which is why anesthesia works less well there.')]),
(10,597165,'A patient with sickle cell disease','A 24-year-old woman with sickle cell disease arrives for a routine cleaning. She reports occasional pain crises and is fatigued. After the appointment, the instruments are cleaned and sterilized in an autoclave.',
 [('Sickle cell disease is caused by a change in which level of hemoglobin structure?',['primary','secondary','tertiary','quaternary'],0,'One amino acid in the &beta; chain is replaced (glutamate &rarr; valine): a change in the amino acid sequence, the primary structure. The change in shape and clumping follows from it (Section 10.6).'),
  ('In sickle hemoglobin, glutamate is replaced by valine. This swaps',['an acidic, charged side chain for a nonpolar one','a nonpolar side chain for an acidic one','a basic side chain for an acidic one','a polar neutral side chain for a basic one'],0,'Glutamate has a COO<sup>&minus;</sup> side chain; valine&rsquo;s side chain is a nonpolar hydrocarbon. The nonpolar patch makes hemoglobin molecules stick together.'),
  ('An autoclave kills bacteria on instruments mainly because heat',['denatures their proteins by disrupting secondary and tertiary structure','hydrolyzes every peptide bond into free amino acids','oxidizes their DNA into CO<sub>2</sub>','converts their lipids into soap'],0,'Denaturation disrupts the weak interactions that hold a protein&rsquo;s shape; the peptide bonds (primary structure) survive (Section 10.10).')]),
(11,597174,'Bleeding gums and a blood thinner','A 70-year-old man with a limited diet has swollen gums that bleed easily, and his health history lists warfarin for atrial fibrillation. The hygienist notes a possible vitamin C deficiency and plans for extra bleeding.',
 [('Vitamin C deficiency (scurvy) causes fragile, bleeding gums because vitamin C is needed',['as a cofactor for the enzyme that hydroxylates proline in collagen','as the precursor of the clotting factors','to make the phospholipids of gum tissue','to break down fibrin clots'],0,'Without vitamin C, collagen is not properly hydroxylated and the connective tissue of the gums weakens (Section 11.5).'),
  ('Vitamin C is a',['water-soluble vitamin with little storage in the body','fat-soluble vitamin stored in the liver','coenzyme form of vitamin K','steroid hormone'],0,'Vitamin C and the B vitamins are water-soluble and must be eaten regularly; vitamins A, D, E and K are fat-soluble.'),
  ('Warfarin lowers clotting by interfering with vitamin K. Vitamin K is',['a fat-soluble vitamin needed to activate several clotting factors','a water-soluble vitamin needed for collagen','a B vitamin that carries acetyl groups','the enzyme that dissolves clots'],0,'Vitamin K is fat-soluble and is required to activate clotting factors; warfarin blocks its recycling, so the patient bleeds more easily.')]),
(12,597185,'A cold sore on the day of the appointment','A 32-year-old woman arrives for her recall appointment with an active, crusting cold sore (herpes labialis) on her lower lip. She says her physician prescribed acyclovir. Radiographs are due today.',
 [('The best plan for elective treatment is to',['reschedule until the lesion has healed','proceed, using extra lip lubricant','proceed, since herpes is not spread by contact','apply acyclovir and continue immediately'],0,'An active lesion is contagious and can be spread to other sites; elective care waits until it heals (Section 12.7).'),
  ('Acyclovir stops the virus from',['replicating its DNA, because the drug has no 3&prime;-OH and terminates the chain','making proteins at the ribosome','attaching to the cell membrane','transcribing RNA into DNA'],0,'Viral DNA polymerase adds acyclovir to the growing strand, but without a 3&prime;-OH the next phosphodiester bond cannot form.'),
  ('Dental radiographs follow the ALARA principle because ionizing radiation',['can damage DNA and cause mutations','denatures salivary enzymes','hydrolyzes the enamel','oxidizes fatty acids in the gums'],0,'Ionizing radiation can break DNA strands and alter bases, so exposure is kept as low as reasonably achievable (Section 12.6).')]),
(13,597199,'Shaky and sweaty in the chair','A 27-year-old man with type 1 diabetes took his morning insulin but skipped breakfast to make an early appointment. Twenty minutes in, he becomes shaky, sweaty and confused, but he is conscious and can swallow.',
 [('His symptoms most likely indicate',['hypoglycemia (low blood glucose)','hyperglycemia (high blood glucose)','diabetic ketoacidosis','an allergic reaction to latex'],0,'Insulin without food drives blood glucose down; shakiness, sweating and confusion are classic signs of hypoglycemia (Section 13.7).'),
  ('A glucose gel or fruit juice raises his blood glucose quickly because',['glucose is a monosaccharide that is absorbed without digestion','glucose must first be hydrolyzed by salivary amylase','juice contains glycogen','sugar is converted to fat first'],0,'Monosaccharides need no digestion and enter the blood directly; starch must first be hydrolyzed (Section 13.3).'),
  ('Which hormone raises blood glucose by stimulating glycogen breakdown in the liver?',['glucagon','insulin','aldosterone','oxytocin'],0,'Glucagon (and epinephrine) trigger glycogenolysis; insulin does the opposite (Section 13.8).')]),
(14,597206,'A tired patient with anemia','A 45-year-old woman with iron-deficiency anemia says she is tired all the time and gets short of breath on the stairs. Her hemoglobin is low, so less oxygen reaches her tissues.',
 [('In the electron transport chain, the final electron acceptor is',['O<sub>2</sub>, which is reduced to water','NAD<sup>+</sup>','CO<sub>2</sub>','glucose'],0,'Complex IV passes electrons to O<sub>2</sub>, making H<sub>2</sub>O; without enough O<sub>2</sub> the chain slows (Section 14.4).'),
  ('Most of the ATP from one glucose molecule is made by',['oxidative phosphorylation through ATP synthase','glycolysis','substrate-level phosphorylation in the citric acid cycle','digestion'],0,'About 26&ndash;28 of the roughly 30&ndash;32 ATP per glucose come from oxidative phosphorylation (Section 14.5).'),
  ('When tissues are short of oxygen, cells keep glycolysis running by converting pyruvate to',['lactate','acetyl CoA','oxaloacetate','urea'],0,'Reducing pyruvate to lactate regenerates NAD<sup>+</sup> for glycolysis when the chain cannot (Section 13.5).')]),
(15,597219,'Fruity breath','A 16-year-old with type 1 diabetes has missed several insulin doses. At the appointment the hygienist notices a fruity odor on his breath and rapid, deep breathing, and refers him for immediate medical care.',
 [('The fruity odor comes from',['acetone, a ketone body','ethanol','lactic acid','ammonia'],0,'Acetone forms from acetoacetate and is exhaled (Section 15.7).'),
  ('Ketone bodies are made in the liver from',['acetyl CoA produced by fatty acid oxidation','glucose produced by gluconeogenesis','urea from the urea cycle','amino acids released by digestion'],0,'Without insulin, fat breakdown floods the liver with acetyl CoA, which is turned into ketone bodies (Sections 15.3 and 15.7).'),
  ('The rapid, deep breathing is the body&rsquo;s attempt to correct',['metabolic acidosis caused by the acidic ketone bodies','alkalosis caused by excess bicarbonate','low blood glucose','high blood ammonia'],0,'Acetoacetic acid and &beta;-hydroxybutyric acid lower blood pH; breathing off CO<sub>2</sub> partly compensates.')]),
]
L='ABCD'
out={}
for ch,pid,title,scen,qs in SETS:
    h=f'<div class="mt-section"><h2 class="editable">Board-Style Case Set: {title}</h2>\n<p><em>Health-care licensing exams such as the National Board Dental Hygiene Examination use case sets: a short patient scenario followed by several questions. Read the case, then answer each question.</em></p>\n<div class="box-note" style="border-left:6px solid #2d8a6a;"><p class="boxtitle">The case</p><p>{scen}</p></div>\n'
    for i,(q,opts,ans,why) in enumerate(qs,1):
        h+=f'<div class="box-exercise"><p class="boxtitle">Case Set Question {ch}.{i}</p><p>{q}</p><ol style="list-style-type:upper-alpha">'+''.join(f'<li>{o}</li>' for o in opts)+f'</ol><details><summary>Answer</summary><div><strong>{L[ans]}.</strong> {why}</div></details></div>\n'
    h+='<p style="font-size:0.9em;color:#555;">Case set by Daniel Kwasniewski, Fresno City College, CC BY 4.0.</p></div>\n'
    out[pid]=h
json.dump({str(k):v for k,v in out.items()},open('/home/claude/textbook/sections/boardsets/boardsets.json','w'))
print(len(out))
